package cl.bolsillo.app;
import android.content.Context;import android.view.*;import android.widget.*;
/** Horizontal section gestures avoid nested carousels, vertical scrolls and system back edges. */
final class SwipeScroll extends ScrollView {
 Runnable left,right;float startX,startY;boolean vertical,nested,dragging;VelocityTracker tracker;
 SwipeScroll(Context c){super(c);}
 boolean horizontalAt(View view,float x,float y){if(view instanceof HorizontalScrollView||view instanceof FlowChart&&view.isClickable())return true;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=group.getChildCount()-1;i>=0;i--){View child=group.getChildAt(i);float cx=x+group.getScrollX()-child.getLeft(),cy=y+group.getScrollY()-child.getTop();if(cx>=0&&cy>=0&&cx<child.getWidth()&&cy<child.getHeight()&&horizontalAt(child,cx,cy))return true;}}return false;}
 void settle(){if(getChildCount()>0)PageMotion.settle(getChildAt(0));}
 @Override public boolean dispatchTouchEvent(MotionEvent e){if(left==null||right==null)return super.dispatchTouchEvent(e);int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){startX=e.getX();startY=e.getY();vertical=dragging=false;nested=horizontalAt(this,startX,startY)||startX<Glass.dp(getContext(),24)||startX>getWidth()-Glass.dp(getContext(),24);if(tracker!=null)tracker.recycle();tracker=VelocityTracker.obtain();if(getChildCount()>0)PageMotion.reset(getChildAt(0));}if(tracker!=null)tracker.addMovement(e);float dx=e.getX()-startX,dy=e.getY()-startY;if(action==MotionEvent.ACTION_MOVE&&!nested){if(Math.abs(dy)>Glass.dp(getContext(),16)&&Math.abs(dy)>Math.abs(dx))vertical=true;if(!vertical&&Math.abs(dx)>Glass.dp(getContext(),26)&&Math.abs(dx)>Math.abs(dy)*1.4f){if(!dragging){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();dragging=true;}if(getChildCount()>0)getChildAt(0).setTranslationX(dx*.15f);return true;}}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL){float speed=0;if(tracker!=null){tracker.computeCurrentVelocity(1000);speed=tracker.getXVelocity();tracker.recycle();tracker=null;}boolean commit=action==MotionEvent.ACTION_UP&&!nested&&!vertical&&Math.abs(dx)>Math.abs(dy)*1.4f&&(Math.abs(dx)>Glass.dp(getContext(),75)||Math.abs(dx)>Glass.dp(getContext(),25)&&Math.abs(speed)>Glass.dp(getContext(),500));if(commit){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();Runnable change=dx<0?left:right;if(getContext() instanceof MainActivity)((MainActivity)getContext()).entryDirection=dx<0?1:-1;change.run();return true;}if(dragging){settle();return true;}}return super.dispatchTouchEvent(e);}
 @Override protected void onDetachedFromWindow(){if(tracker!=null){tracker.recycle();tracker=null;}if(getChildCount()>0)PageMotion.reset(getChildAt(0));super.onDetachedFromWindow();}
}
